IDIOMAS = ["en", "de", "fr", "es", "pt", "it", "ru", "ja", "zh"]
NOMBRES = {"en": "English", "de": "Deutsch", "fr": "Francais", "es": "Espanol",
           "pt": "Portugues", "it": "Italiano", "ru": "Ruso", "ja": "Japones", "zh": "Chino"}

# Los del panel, iguales en los nueve idiomas (ver scripts/panel.py).
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from panel import PANEL  # noqa: E402

for clave, texto in PANEL.items():
    T[clave] = {i: texto for i in IDIOMAS}

faltan = [(k, i) for k, v in T.items() for i in IDIOMAS if i not in v or not v[i]]
if faltan:
    raise SystemExit("faltan traducciones: %s" % faltan[:5])

destino = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "i18n", "locales")
os.makedirs(destino, exist_ok=True)


def anidar(plano):
    salida = {}
    for clave, valor in plano.items():
        partes = clave.split(".")
        nodo = salida
        for p in partes[:-1]:
            nodo = nodo.setdefault(p, {})
        nodo[partes[-1]] = valor
    return salida


cabecera = (
    "/* %s - %s.\n"
    " *\n"
    " * Generado desde la tabla de traducciones. Para agregar un texto,\n"
    " * agregalo en los NUEVE idiomas: una pantalla a medio traducir se ve\n"
    " * peor que una en un idioma solo.\n"
    " */\n"
)

for idioma in IDIOMAS:
    plano = {k: v[idioma] for k, v in T.items()}
    cuerpo = json.dumps(anidar(plano), ensure_ascii=False, indent=2)
    texto = (cabecera % (NOMBRES[idioma], idioma)) + "export default " + cuerpo + ";\n"
    io.open(os.path.join(destino, idioma + ".js"), "w", encoding="utf-8", newline="\n").write(texto)

print("escritos %d idiomas x %d textos" % (len(IDIOMAS), len(T)))
